        public static void Open(Window owner, DeepSystemsContext ctx) { if (ctx == null) return; Load(ctx); OpenHub(owner, ctx, WorldKernel.ExternalIndex(ctx, false)); }

        public static void OpenFromWorldNode(Window owner, DeepSystemsContext ctx, WorldIndex index, string nodeId)
        {
            if (ctx == null || index == null || String.IsNullOrWhiteSpace(nodeId)) return; WorldNode node; if (!index.Nodes.TryGetValue(nodeId, out node)) { Open(owner, ctx); return; }
            string fp = HashText((node.Id ?? "") + "|" + (node.Kind ?? "") + "|" + (node.Label ?? "") + "|" + (node.Fingerprint ?? ""));
            OpenProjection(owner, ctx, index, "WORLD", node.Id, fp, delegate { EconomicModel m = StarterEconomy("World economy · " + (node.Label ?? node.Kind ?? "World object"), "Synthetic stock-flow projection from one stable World Passport."); m.EvidenceNodeIds.Add(node.Id); return m; });
        }

        public static void OpenFromCivilResolution(Window owner, DeepSystemsContext ctx, WorldIndex index, CivilResolution source)
        {
            if (ctx == null || source == null) return; string fp = HashText((source.Id ?? "") + "|" + (source.Title ?? "") + "|" + (source.Proposition ?? "") + "|" + (source.Status ?? "") + "|" + String.Join("|", (source.EvidenceNodeIds ?? new List<string>()).OrderBy(x => x).ToArray()));
            OpenProjection(owner, ctx, index ?? WorldKernel.ExternalIndex(ctx, false), "CIVILIZATION", source.Id, fp, delegate { EconomicModel m = StarterEconomy("Political economy · " + (source.Title ?? "Civil resolution"), "Fiscal, labor, enterprise and distributional lens over a civil resolution without converting adoption into implementation authority."); m.Assumptions.Add("Civil proposition: " + (source.Proposition ?? "")); m.EvidenceNodeIds.AddRange(source.EvidenceNodeIds ?? new List<string>()); return m; });
        }

