        private static void OpenProjection(Window owner, DeepSystemsContext ctx, WorldIndex index, string sourceKind, string sourceId, string fingerprint, Func<EconomicModel> factory)
        {
            Load(ctx); List<EconomicModel> existing = Store.Models.Where(x => Eq(x.SourceKind, sourceKind) && Eq(x.SourceId, sourceId)).OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).ToList(); EconomicModel exact = existing.FirstOrDefault(x => Eq(x.SourceFingerprint, fingerprint)); if (exact != null) { OpenModel(owner, ctx, index, exact); return; }
            if (existing.Count > 0) { MessageBoxResult choice = MessageBox.Show(owner, "The upstream source has changed since the latest economic projection.\n\nYES  Create a fingerprint-bound child economy\nNO   Open the historical economy\nCANCEL   Leave everything unchanged", "SOURCE DRIFT · ECONOMIC CIVILIZATION", MessageBoxButton.YesNoCancel, MessageBoxImage.Warning); if (choice == MessageBoxResult.No) { OpenModel(owner, ctx, index, existing[0]); return; } if (choice != MessageBoxResult.Yes) return; }
            EconomicModel model = factory == null ? StarterEconomy("Untitled economy", "Declared synthetic economy.") : factory(); if (model == null) return; model.Id = Id("economic-model"); model.ParentModelId = existing.Count == 0 ? null : existing[0].Id; model.SourceKind = sourceKind; model.SourceId = sourceId; model.SourceFingerprint = fingerprint; model.CreatedUtc = Now(); model.UpdatedUtc = model.CreatedUtc; model.Revision = existing.Count == 0 ? 1 : Math.Max(1, existing[0].Revision) + 1; Store.Models.Insert(0, model); Save(ctx); AppendLedger(ctx, "ECONOMY_PROJECTED", model.Id, sourceKind + ":" + sourceId + (existing.Count == 0 ? "" : " · source drift child of " + existing[0].Id), EconomicKernel.Fingerprint(model), ""); OpenModel(owner, ctx, index, model);
        }

        private static void OpenHub(Window owner, DeepSystemsContext ctx, WorldIndex index)
        {
            Window w = Shell(owner, "ECONOMIC CIVILIZATION · STOCK-FLOW COMMAND", 1500, 900); DockPanel root = new DockPanel { Background = Bg };
            StackPanel head = new StackPanel { Margin = new Thickness(28, 24, 28, 14) }; head.Children.Add(Txt("ECONOMIC CIVILIZATION", 30, Accent, FontWeights.Bold)); head.Children.Add(Txt("HOUSEHOLDS · FIRMS · GOODS · LABOR · CREDIT · CONTRACTS · GOVERNMENT · TRADE · DISTRIBUTION", 12, Blue, FontWeights.SemiBold)); head.Children.Add(Txt("A persistent synthetic economy laboratory with double-entry transaction journals, endogenous production and prices, credit/default propagation, national accounts, distributional indicators, policy counterfactuals and fingerprint-bound provenance. No output is a forecast, entitlement decision, lending decision, price instruction, tax order or execution authority.", 13, Muted, FontWeights.Normal)); head.Children.Add(Txt(CensusLine(), 12, Amber, FontWeights.SemiBold)); DockPanel.SetDock(head, Dock.Top); root.Children.Add(head);
            ScrollViewer scroll = new ScrollViewer { VerticalScrollBarVisibility = ScrollBarVisibility.Auto }; WrapPanel chambers = new WrapPanel { Margin = new Thickness(24, 0, 24, 24) };
            chambers.Children.Add(Tile("01 · ECONOMY REGISTRY", "Open a persistent authored or projected economy.", delegate { OpenRegistry(w, ctx, index); }));
