            chambers.Children.Add(Tile("03 · TRANSACTION CLEARINGHOUSE", "Inspect certified double-entry journals.", delegate { OpenLatestJournal(w, ctx); }));
            chambers.Children.Add(Tile("04 · HOUSEHOLD SECTOR", "Population cohorts, labor, income, cash, wealth and debt.", delegate { WithModel(w, ctx, m => OpenRows(w, "HOUSEHOLD SECTOR", m.Households, "Synthetic cohorts and declared balance sheets")); }));
            chambers.Children.Add(Tile("05 · ENTERPRISE SECTOR", "Firms, capital, inventories, wages, markups and solvency.", delegate { WithModel(w, ctx, m => OpenRows(w, "ENTERPRISE SECTOR", m.Firms, "Synthetic enterprises only")); }));
