        private static void OpenRegistry(Window owner, DeepSystemsContext ctx, WorldIndex index)
        {
            Load(ctx); EconomicModel model = ChooseObject(owner, "ECONOMY REGISTRY", "Choose an authored, projected or forked economic world", Store.Models.OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).Cast<object>().ToList()) as EconomicModel; if (model != null) OpenModel(owner, ctx, index, model);
        }

        private static void OpenModel(Window owner, DeepSystemsContext ctx, WorldIndex index, EconomicModel model)
        {
            NormalizeModel(model); Window w = Shell(owner, "ECONOMIC WORLD · " + (model.Name ?? model.Id), 1580, 920); DockPanel root = new DockPanel { Background = Bg };
            StackPanel head = new StackPanel { Margin = new Thickness(22, 18, 22, 10) }; head.Children.Add(Txt(model.Name ?? model.Id, 25, Accent, FontWeights.Bold)); head.Children.Add(Txt((model.Description ?? "") + "\n" + ModelCensus(model) + "   ·   fingerprint " + Short(EconomicKernel.Fingerprint(model), 24), 12, Muted, FontWeights.Normal)); DockPanel.SetDock(head, Dock.Top); root.Children.Add(head);
            WrapPanel tools = new WrapPanel { Margin = new Thickness(18, 0, 18, 12) };
            tools.Children.Add(Btn("SAVE REVISION", delegate { model.Revision++; model.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, "ECONOMY_SAVED", model.Id, model.Name, EconomicKernel.Fingerprint(model), ""); }));
            tools.Children.Add(Btn("RUN ECONOMY", delegate { RunSimulation(w, ctx, model); })); tools.Children.Add(Btn("STRESS WORLDS", delegate { RunStress(w, ctx, model); })); tools.Children.Add(Btn("POLICY SWEEP", delegate { RunPolicySweep(w, ctx, model); })); tools.Children.Add(Btn("SUPPLY CHAIN", delegate { RunStructure(w, ctx, model, false); }));
            tools.Children.Add(Btn("PREREGISTER", delegate { CreateCapsule(w, ctx, model); })); tools.Children.Add(Btn("FREEZE BASELINE", delegate { FreezeBaseline(w, ctx, model); })); tools.Children.Add(Btn("CREATE DOSSIER", delegate { CreateDossier(w, ctx, model); })); tools.Children.Add(Btn("FORK", delegate { ForkModel(w, ctx, index, model); }));
            tools.Children.Add(Btn("MAP ECONOMIC GEOGRAPHY", delegate { SpatialWorldCartography.OpenFromEconomicModel(w, ctx, index, model); }));
            tools.Children.Add(Btn("DISTRIBUTE ECONOMIC LEDGER", delegate { DistributedSystemsPlanetarium.OpenFromEconomicModel(w, ctx, index, model); }));
            tools.Children.Add(Btn("DEFEND ECONOMIC WORLD", delegate { AdversarialSecurityFortress.OpenFromEconomicModel(w, ctx, index, model); }));
            tools.Children.Add(Btn("PROJECT ECONOMIC DATA", delegate { DataFoundry.OpenFromEconomicModel(w, ctx, index, model); }));
            tools.Children.Add(Btn("ADD REGION", delegate { AddRegion(w, model); RefreshModel(w, ctx, index, model); })); tools.Children.Add(Btn("ADD GOOD", delegate { AddGood(w, model); RefreshModel(w, ctx, index, model); })); tools.Children.Add(Btn("ADD HOUSEHOLD", delegate { AddHousehold(w, model); RefreshModel(w, ctx, index, model); })); tools.Children.Add(Btn("ADD FIRM", delegate { AddFirm(w, model); RefreshModel(w, ctx, index, model); })); tools.Children.Add(Btn("ADD RECIPE", delegate { AddRecipe(w, model); RefreshModel(w, ctx, index, model); })); tools.Children.Add(Btn("ADD BANK", delegate { AddBank(w, model); RefreshModel(w, ctx, index, model); })); tools.Children.Add(Btn("ADD GOVERNMENT", delegate { AddGovernment(w, model); RefreshModel(w, ctx, index, model); })); tools.Children.Add(Btn("ADD CONTRACT", delegate { AddContract(w, model); RefreshModel(w, ctx, index, model); })); tools.Children.Add(Btn("ADD LOAN", delegate { AddLoan(w, model); RefreshModel(w, ctx, index, model); })); tools.Children.Add(Btn("ADD SCENARIO", delegate { AddScenario(w, model); RefreshModel(w, ctx, index, model); }));
            tools.Children.Add(Btn(Active(model.Status) ? "ARCHIVE" : "REACTIVATE", delegate { model.Status = Active(model.Status) ? "ARCHIVED" : "ACTIVE"; model.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, "ECONOMY_" + model.Status, model.Id, model.Name, EconomicKernel.Fingerprint(model), ""); w.Close(); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, model.Name, model, StorePath(ctx), "$models:" + model.Id, "ECONOMIC CIVILIZATION › ECONOMY"); }));
            DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools);
            Grid body = new Grid(); for (int i = 0; i < 4; i++) body.ColumnDefinitions.Add(new ColumnDefinition());
            ListBox people = List(), enterprise = List(), institutions = List(), artifacts = List();
            people.ItemsSource = model.Households.Cast<object>().Concat(model.Regions.Cast<object>()).ToList(); enterprise.ItemsSource = model.Firms.Cast<object>().Concat(model.Recipes.Cast<object>()).Concat(model.Goods.Cast<object>()).ToList(); institutions.ItemsSource = model.Banks.Cast<object>().Concat(model.Governments.Cast<object>()).Concat(model.Contracts.Cast<object>()).Concat(model.Loans.Cast<object>()).Concat(model.Scenarios.Cast<object>()).ToList(); artifacts.ItemsSource = ArtifactsFor(model.Id);
            Grid.SetColumn(people, 0); Grid.SetColumn(enterprise, 1); Grid.SetColumn(institutions, 2); Grid.SetColumn(artifacts, 3); body.Children.Add(people); body.Children.Add(enterprise); body.Children.Add(institutions); body.Children.Add(artifacts); root.Children.Add(body); w.Content = root; w.Show();
        }

        private static void RefreshModel(Window window, DeepSystemsContext ctx, WorldIndex index, EconomicModel model) { if (window == null || model == null) return; model.Revision++; model.UpdatedUtc = Now(); Save(ctx); AppendLedger(ctx, "ECONOMY_ENTITY_ADDED", model.Id, ModelCensus(model), EconomicKernel.Fingerprint(model), ""); window.Close(); OpenModel(window.Owner, ctx, index, model); }

        private static void CreateModel(Window owner, DeepSystemsContext ctx, WorldIndex index)
        {
            string name = Prompt(owner, "ECONOMIC CIVILIZATION FORGE", "Economy name", "Interdependent two-region civilization"); if (String.IsNullOrWhiteSpace(name)) return; string description = PromptLarge(owner, "ECONOMIC CHARTER", "Scope, institutions, time scale and authority boundary", "A synthetic civilization containing households, firms, production chains, prices, labor, banks, credit, contracts, government, taxation, transfers, trade, shortages and defaults."); if (description == null) return; EconomicModel model = StarterEconomy(name.Trim(), description.Trim()); model.Id = Id("economic-model"); model.Horizon = Integer(Prompt(owner, "SIMULATION HORIZON", "1..512 economic periods", "36"), 36, 1, 512); model.Seed = Integer(Prompt(owner, "DETERMINISTIC SEED", "Signed integer seed", "1337"), 1337, Int32.MinValue, Int32.MaxValue); model.CreatedUtc = Now(); model.UpdatedUtc = model.CreatedUtc; Store.Models.Insert(0, model); Save(ctx); AppendLedger(ctx, "ECONOMY_CREATED", model.Id, model.Name, EconomicKernel.Fingerprint(model), ""); OpenModel(owner, ctx, index, model);
        }

        private static void RunSimulation(Window owner, DeepSystemsContext ctx, EconomicModel model)
        {
            EcoScenario scenario = null; if (model.Scenarios.Count > 0) { List<object> choices = new List<object> { "DECLARED BASELINE" }; choices.AddRange(model.Scenarios.Cast<object>()); object choice = ChooseObject(owner, "ECONOMIC WORLD", "Choose baseline or a declared shock world", choices); if (choice == null) return; scenario = choice as EcoScenario; }
            EcoSimulationResult result = EconomicKernel.Simulate(model, scenario, null); string created = Now(), fp = EconomicKernel.Fingerprint(model), cert = HashText(fp + "|" + created + "|" + Json.Serialize(result)); EcoRunArtifact artifact = new EcoRunArtifact { Id = Id("economic-run"), ModelId = model.Id, CreatedUtc = created, ModelFingerprint = fp, CertificateHash = cert, Label = scenario == null ? "DECLARED BASELINE" : "SCENARIO · " + scenario.Name, Result = result }; Store.Runs.Insert(0, artifact); Save(ctx); AppendLedger(ctx, "ECONOMIC_RUN_CERTIFIED", artifact.Id, artifact.Label, fp, cert); OpenRows(owner, "STOCK-FLOW TRAJECTORY", new object[] { artifact }.Concat(result.Periods.Cast<object>()).Concat(result.FinalEntities.Cast<object>()).Concat(result.Defaults.Cast<object>()).Concat(result.Audit.Cast<object>()), "Certificate " + cert + " · synthetic conditional trajectory, not forecast");
        }

        private static void RunStress(Window owner, DeepSystemsContext ctx, EconomicModel model)
        {
            EcoStressResult result = EconomicKernel.Stress(model); string created = Now(), fp = EconomicKernel.Fingerprint(model), cert = HashText(fp + "|" + created + "|" + Json.Serialize(result)); EcoStressArtifact artifact = new EcoStressArtifact { Id = Id("economic-stress"), ModelId = model.Id, CreatedUtc = created, ModelFingerprint = fp, CertificateHash = cert, Result = result }; Store.StressRuns.Insert(0, artifact); Save(ctx); AppendLedger(ctx, "ECONOMIC_STRESS_CERTIFIED", artifact.Id, model.Name, fp, cert); OpenRows(owner, "CRISIS PLANETARIUM", new object[] { artifact, result }.Concat(result.Scores.Cast<object>()).Concat(result.Audit.Cast<object>()), "Weighted scenario coordinates are declarations, not probabilities · certificate " + cert);
        }

        private static void RunPolicySweep(Window owner, DeepSystemsContext ctx, EconomicModel model)
        {
            string key = Prompt(owner, "POLICY COORDINATE", "income_tax_rate, sales_tax_rate, corporate_tax_rate, payroll_tax_rate, transfer_per_household, base_interest_rate, capital_ratio, minimum_wage or price_adjustment_speed", "base_interest_rate"); if (String.IsNullOrWhiteSpace(key)) return; double minimum = Number(Prompt(owner, "SWEEP MINIMUM", "Inclusive policy coordinate", "0.01"), 0.01), maximum = Number(Prompt(owner, "SWEEP MAXIMUM", "Inclusive policy coordinate", "0.12"), 0.12); int steps = Integer(Prompt(owner, "SWEEP RESOLUTION", "2..32 deterministic worlds", "9"), 9, 2, 32); EcoPolicySweepResult result = EconomicKernel.SweepPolicy(model, key.Trim(), minimum, maximum, steps); string created = Now(), fp = EconomicKernel.Fingerprint(model), cert = HashText(fp + "|" + created + "|" + Json.Serialize(result)); EcoPolicyArtifact artifact = new EcoPolicyArtifact { Id = Id("economic-policy-space"), ModelId = model.Id, CreatedUtc = created, ModelFingerprint = fp, CertificateHash = cert, Result = result }; Store.PolicySweeps.Insert(0, artifact); Save(ctx); AppendLedger(ctx, "POLICY_SPACE_CERTIFIED", artifact.Id, key + " · " + steps + " worlds", fp, cert); OpenRows(owner, "POLICY COUNTERFACTUAL SPACE", new object[] { artifact, result }.Concat(result.Points.Cast<object>()).Concat(result.Audit.Cast<object>()), "Internal rule-world comparison only · certificate " + cert);
        }

        private static void RunStructure(Window owner, DeepSystemsContext ctx, EconomicModel model, bool marketOnly)
        {
            EcoSupplyChainResult supply = EconomicKernel.AnalyzeSupplyChain(model); EcoSimulationResult simulation = EconomicKernel.Simulate(model, null, null); List<EcoMarketStructureRecord> markets = EconomicKernel.AnalyzeMarketStructure(model, simulation); string created = Now(), fp = EconomicKernel.Fingerprint(model), cert = HashText(fp + "|" + created + "|" + supply.CertificateHash + "|" + String.Join(";", markets.Select(x => x.ToString()).ToArray())); EcoStructureArtifact artifact = new EcoStructureArtifact { Id = Id("economic-structure"), ModelId = model.Id, CreatedUtc = created, ModelFingerprint = fp, CertificateHash = cert, SupplyChain = supply, Markets = markets }; Store.Structures.Insert(0, artifact); Save(ctx); AppendLedger(ctx, "ECONOMIC_STRUCTURE_CERTIFIED", artifact.Id, model.Name, fp, cert); IEnumerable<object> rows = marketOnly ? markets.Cast<object>() : new object[] { artifact, supply }.Concat(supply.Nodes.Cast<object>()).Concat(supply.StrongComponents.Select(x => (object)("CYCLE COMPONENT · " + String.Join(" → ", x.ToArray())))).Concat(supply.Audit.Cast<object>()); OpenRows(owner, marketOnly ? "MARKET STRUCTURE" : "SUPPLY-CHAIN TOMOGRAPHY", rows, "Structural model map · certificate " + cert);
        }

        private static void AddRegion(Window owner, EconomicModel model) { string name = Prompt(owner, "ADD ECONOMIC REGION", "Region name", "New region"); if (String.IsNullOrWhiteSpace(name)) return; string id = UniqueKey(name, model.Regions.Select(x => x.Id)); model.Regions.Add(new EcoRegion { Id = id, Name = name.Trim(), Currency = Prompt(owner, "CURRENCY", "Declared currency code", "UNIT") ?? "UNIT", ExchangeRateToNumeraire = Number(Prompt(owner, "EXCHANGE RATE", "Units of numeraire per currency unit", "1"), 1), ImportTariffRate = Rate(Prompt(owner, "IMPORT TARIFF", "0..1", "0.03"), 0.03) }); }
