        private static void AddFirm(Window owner, EconomicModel model) { if (model.Regions.Count == 0) { MessageBox.Show(owner, "Create a region first.", "ENTERPRISE SECTOR"); return; } string name = Prompt(owner, "ADD FIRM", "Enterprise name", "New enterprise"); if (String.IsNullOrWhiteSpace(name)) return; model.Firms.Add(new EcoFirm { Id = UniqueKey(name, model.Firms.Select(x => x.Id)), Name = name.Trim(), RegionId = Prompt(owner, "REGION ID", "Existing region ID", model.Regions[0].Id) ?? model.Regions[0].Id, BankId = Prompt(owner, "BANK ID", "Existing bank ID or blank", model.Banks.FirstOrDefault() == null ? "" : model.Banks[0].Id), Cash = Math.Max(0, Number(Prompt(owner, "OPENING CASH", "Nonnegative", "25000"), 25000)), Equity = Number(Prompt(owner, "OPENING EQUITY", "Declared book equity", "50000"), 50000), Debt = Math.Max(0, Number(Prompt(owner, "OPENING DEBT", "Nonnegative", "10000"), 10000)), CapitalStock = Math.Max(0, Number(Prompt(owner, "CAPITAL STOCK", "Nonnegative", "75000"), 75000)), CapacityBatches = Math.Max(0, Number(Prompt(owner, "CAPACITY", "Batches per period", "100"), 100)), Productivity = Math.Max(0.000001, Number(Prompt(owner, "PRODUCTIVITY", "Positive multiplier", "1"), 1)), OfferedWage = Math.Max(0, Number(Prompt(owner, "OFFERED WAGE", "Per labor hour", "18"), 18)), Markup = Math.Max(-0.99, Number(Prompt(owner, "MARKUP", "Decimal markup", "0.2"), 0.2)), TargetInventoryPeriods = Math.Max(0, Number(Prompt(owner, "TARGET INVENTORY", "Periods of inputs", "2"), 2)), RequiredSkill = Prompt(owner, "REQUIRED SKILL", "Labor-market skill code", "GENERAL") ?? "GENERAL" }); }
