        private static void AddGovernment(Window owner, EconomicModel model) { if (model.Regions.Count == 0) { MessageBox.Show(owner, "Create a region first.", "FISCAL INSTITUTIONS"); return; } string name = Prompt(owner, "ADD GOVERNMENT", "Government name", "Regional government"); if (String.IsNullOrWhiteSpace(name)) return; model.Governments.Add(new EcoGovernment { Id = UniqueKey(name, model.Governments.Select(x => x.Id)), Name = name.Trim(), RegionId = Prompt(owner, "REGION ID", "Existing region ID", model.Regions[0].Id) ?? model.Regions[0].Id, Cash = Math.Max(0, Number(Prompt(owner, "OPENING CASH", "Nonnegative", "100000"), 100000)), Debt = Math.Max(0, Number(Prompt(owner, "OPENING DEBT", "Nonnegative", "50000"), 50000)), IncomeTaxRate = Rate(Prompt(owner, "INCOME TAX", "0..1", "0.15"), 0.15), SalesTaxRate = Rate(Prompt(owner, "SALES TAX", "0..1", "0.05"), 0.05), CorporateTaxRate = Rate(Prompt(owner, "CORPORATE TAX", "0..1", "0.18"), 0.18), PayrollTaxRate = Rate(Prompt(owner, "PAYROLL TAX", "0..1", "0.03"), 0.03), TransferPerHousehold = Math.Max(0, Number(Prompt(owner, "TRANSFER", "Per represented household per period", "2"), 2)), ProcurementBudget = Math.Max(0, Number(Prompt(owner, "PROCUREMENT BUDGET", "Declared coordinate", "5000"), 5000)) }); }
        private static void AddContract(Window owner, EconomicModel model) { if (model.Firms.Count < 2 || model.Goods.Count == 0) { MessageBox.Show(owner, "Create at least two firms and one good first.", "CONTRACT EXCHANGE"); return; } string buyer = Prompt(owner, "CONTRACT BUYER", "Existing firm ID", model.Firms[0].Id), seller = Prompt(owner, "CONTRACT SELLER", "Existing firm ID", model.Firms[1].Id), good = Prompt(owner, "CONTRACT GOOD", "Existing good ID", model.Goods[0].Id); if (String.IsNullOrWhiteSpace(buyer) || String.IsNullOrWhiteSpace(seller) || String.IsNullOrWhiteSpace(good)) return; model.Contracts.Add(new EcoContract { Id = Id("contract"), BuyerId = buyer.Trim(), SellerId = seller.Trim(), GoodId = good.Trim(), Quantity = Math.Max(0, Number(Prompt(owner, "QUANTITY", "Contract quantity", "100"), 100)), UnitPrice = Math.Max(0, Number(Prompt(owner, "UNIT PRICE", "Zero uses market reference", "10"), 10)), StartPeriod = Integer(Prompt(owner, "START PERIOD", "0..2048", "1"), 1, 0, 2048), DuePeriod = Integer(Prompt(owner, "DUE PERIOD", "0..2048", "12"), 12, 0, 2048), LatePenaltyRate = Math.Max(0, Number(Prompt(owner, "LATE PENALTY", "Per-period decimal", "0.01"), 0.01)) }); }
        private static void AddLoan(Window owner, EconomicModel model) { if (model.Banks.Count == 0 || model.Firms.Count == 0) { MessageBox.Show(owner, "Create at least one bank and firm first.", "CREDIT LEDGER"); return; } string bank = Prompt(owner, "LENDER", "Existing bank ID", model.Banks[0].Id), borrower = Prompt(owner, "BORROWER", "Existing firm ID", model.Firms[0].Id); if (String.IsNullOrWhiteSpace(bank) || String.IsNullOrWhiteSpace(borrower)) return; double principal = Math.Max(0, Number(Prompt(owner, "PRINCIPAL", "Opening loan principal", "10000"), 10000)); model.Loans.Add(new EcoLoan { Id = Id("loan"), BankId = bank.Trim(), BorrowerId = borrower.Trim(), OriginalPrincipal = principal, OutstandingPrincipal = principal, AnnualInterestRate = Number(Prompt(owner, "INTEREST RATE", "Annual decimal", "0.07"), 0.07), RemainingPeriods = Integer(Prompt(owner, "TERM", "Remaining periods", "24"), 24, 1, 2048), CollateralValue = Math.Max(0, Number(Prompt(owner, "COLLATERAL VALUE", "Synthetic coordinate", "15000"), 15000)) }); }
        private static void AddScenario(Window owner, EconomicModel model) { string name = Prompt(owner, "ADD ECONOMIC WORLD", "Scenario name", "Composite stress world"); if (String.IsNullOrWhiteSpace(name)) return; model.Scenarios.Add(new EcoScenario { Id = UniqueKey(name, model.Scenarios.Select(x => x.Id)), Name = name.Trim(), Weight = Math.Max(0, Number(Prompt(owner, "WEIGHT", "Declared scenario weight, not probability", "1"), 1)), HouseholdDemandMultiplier = Math.Max(0, Number(Prompt(owner, "DEMAND MULTIPLIER", "Nonnegative", "0.9"), 0.9)), ProductivityMultiplier = Math.Max(0.000001, Number(Prompt(owner, "PRODUCTIVITY MULTIPLIER", "Positive", "0.9"), 0.9)), InputCostMultiplier = Math.Max(0, Number(Prompt(owner, "INPUT-COST MULTIPLIER", "Nonnegative", "1.15"), 1.15)), WageMultiplier = Math.Max(0, Number(Prompt(owner, "WAGE MULTIPLIER", "Nonnegative", "1"), 1)), CreditAvailabilityMultiplier = Math.Max(0.000001, Number(Prompt(owner, "CREDIT MULTIPLIER", "Positive", "0.7"), 0.7)), TradeFrictionMultiplier = Math.Max(0, Number(Prompt(owner, "TRADE-FRICTION MULTIPLIER", "Nonnegative", "1.5"), 1.5)), ExogenousInflationMultiplier = Math.Max(0.000001, Number(Prompt(owner, "INFLATION MULTIPLIER", "Positive per-period price multiplier", "1.01"), 1.01)), Assumptions = new List<string> { "Scenario multipliers are declared conditional coordinates and are not calibrated probabilities." } }); }

        private static void CreateCapsule(Window owner, DeepSystemsContext ctx, EconomicModel model)
        {
            string title = Prompt(owner, "PREREGISTER POLICY EXPERIMENT", "Capsule title", "Economic counterfactual · " + model.Name); if (String.IsNullOrWhiteSpace(title)) return; string question = PromptLarge(owner, "FROZEN QUESTION", "Question to lock before evaluating the policy space", "Under this exact synthetic economy fingerprint, how does the declared policy coordinate change production, prices, employment, shortages, distribution, fiscal balance and defaults?"); if (question == null) return; string key = Prompt(owner, "POLICY COORDINATE", "Frozen parameter key", "base_interest_rate"); if (String.IsNullOrWhiteSpace(key)) return; EcoExperimentCapsule c = new EcoExperimentCapsule { Id = Id("economic-capsule"), ModelId = model.Id, Title = title.Trim(), Question = question.Trim(), Hypothesis = PromptLarge(owner, "HYPOTHESIS", "Directional claim and explicit failure condition", "The intervention improves the declared primary metric without worsening unemployment, shortages, inequality or defaults beyond the stated acceptance rule."), ParameterKey = key.Trim(), Minimum = Number(Prompt(owner, "MINIMUM", "Inclusive coordinate", "0.01"), 0.01), Maximum = Number(Prompt(owner, "MAXIMUM", "Inclusive coordinate", "0.12"), 0.12), Steps = Integer(Prompt(owner, "STEPS", "2..32", "9"), 9, 2, 32), PrimaryMetric = Prompt(owner, "PRIMARY METRIC", "Exact metric name", "terminal_nominal_gdp") ?? "terminal_nominal_gdp", FrozenUtc = Now(), ModelFingerprint = EconomicKernel.Fingerprint(model), FrozenParameters = new Dictionary<string, double>(model.Parameters, StringComparer.OrdinalIgnoreCase), Assumptions = new List<string>(model.Assumptions), EvidenceNodeIds = new List<string>(model.EvidenceNodeIds) }; c.CertificateHash = HashText(Json.Serialize(c) + "|" + c.ModelFingerprint); Store.Capsules.Insert(0, c); Save(ctx); AppendLedger(ctx, "POLICY_EXPERIMENT_PREREGISTERED", c.Id, c.Title, c.ModelFingerprint, c.CertificateHash); OpenRows(owner, "PREREGISTERED POLICY CAPSULE", c, c.AuthorityBoundary);
        }

        private static void FreezeBaseline(Window owner, DeepSystemsContext ctx, EconomicModel model) { string name = Prompt(owner, "FREEZE ECONOMIC BASELINE", "Immutable baseline name", model.Name + " · baseline " + Now()); if (String.IsNullOrWhiteSpace(name)) return; string reason = PromptLarge(owner, "BASELINE RATIONALE", "Why this exact economic world must remain recoverable", "Preserve an exact reference before altering populations, firms, recipes, balance sheets, contracts, policies, shocks or time horizon."); if (reason == null) return; string snapshot = Json.Serialize(model), fp = EconomicKernel.Fingerprint(model); EcoModelBaseline parent = Store.Baselines.FirstOrDefault(x => Eq(x.ModelId, model.Id)); EcoModelBaseline baseline = new EcoModelBaseline { Id = Id("economic-baseline"), ModelId = model.Id, ParentBaselineId = parent == null ? null : parent.Id, Name = name.Trim(), Reason = reason.Trim(), Status = "FROZEN", FrozenUtc = Now(), ModelFingerprint = fp, SnapshotJson = snapshot }; baseline.BaselineFingerprint = BaselineFingerprint(baseline); Store.Baselines.Insert(0, baseline); Save(ctx); AppendLedger(ctx, "ECONOMIC_BASELINE_FROZEN", baseline.Id, baseline.Name, fp, baseline.BaselineFingerprint); OpenRows(owner, "IMMUTABLE ECONOMIC BASELINE", baseline, "Recomputed " + BaselineFingerprint(baseline)); }
        private static string BaselineFingerprint(EcoModelBaseline b) { return HashText((b.Id ?? "") + "|" + (b.ModelId ?? "") + "|" + (b.ParentBaselineId ?? "") + "|" + (b.Name ?? "") + "|" + (b.FrozenUtc ?? "") + "|" + (b.Reason ?? "") + "|" + (b.ModelFingerprint ?? "") + "|" + (b.SnapshotJson ?? "")); }

        private static void CreateDossier(Window owner, DeepSystemsContext ctx, EconomicModel model)
        {
            string title = Prompt(owner, "CREATE ECONOMIC DOSSIER", "Dossier title", "Bounded economic interpretation · " + model.Name); if (String.IsNullOrWhiteSpace(title)) return; string interpretation = PromptLarge(owner, "BOUNDED INTERPRETATION", "State only what the declared model and matching artifacts support", "Under the declared entities, accounting identities, behavioral rules and stress coordinates, the attached artifacts describe conditional synthetic trajectories for human review."); if (interpretation == null) return; string fp = EconomicKernel.Fingerprint(model); EcoRunArtifact run = Store.Runs.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, fp)); EcoStressArtifact stress = Store.StressRuns.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, fp)); EcoPolicyArtifact policy = Store.PolicySweeps.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, fp)); EcoStructureArtifact structure = Store.Structures.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, fp)); EcoModelBaseline baseline = Store.Baselines.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, fp)); EcoExperimentCapsule capsule = Store.Capsules.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, fp)); EcoEconomicDossier d = new EcoEconomicDossier { Id = Id("economic-dossier"), ModelId = model.Id, RunId = run == null ? null : run.Id, StressId = stress == null ? null : stress.Id, PolicyId = policy == null ? null : policy.Id, StructureId = structure == null ? null : structure.Id, BaselineId = baseline == null ? null : baseline.Id, CapsuleId = capsule == null ? null : capsule.Id, Title = title.Trim(), CreatedUtc = Now(), UpdatedUtc = Now(), ModelFingerprint = fp, BoundedInterpretation = interpretation.Trim(), EvidenceNodeIds = new List<string>(model.EvidenceNodeIds) }; d.AccountingConditions.Add("All displayed flows use the kernel's balanced synthetic journal and declared opening coordinates."); d.DistributionalEffects.Add("Aggregate gains do not establish cohort consent, fairness, legal validity or welfare improvement."); if (run == null) d.Unknowns.Add("No matching certified temporal trajectory is attached."); if (stress == null) d.Unknowns.Add("No matching crisis stress artifact is attached."); if (policy == null) d.Unknowns.Add("No matching policy counterfactual space is attached."); if (structure == null) d.Unknowns.Add("No matching supply-chain and market-structure artifact is attached."); if (baseline == null) d.Unknowns.Add("No immutable matching model baseline is attached."); if (capsule == null) d.Unknowns.Add("No matching preregistered policy experiment is attached."); d.Unknowns.Add("External measurement, causal identification, institutional behavior, law, politics, implementation and omitted sectors require independent review."); d.Dissent.Add("Absence of recorded dissent is not agreement and cannot authorize action."); Store.Dossiers.Insert(0, d); Save(ctx); AppendLedger(ctx, "ECONOMIC_DOSSIER_CREATED", d.Id, d.Title, fp, ""); OpenRows(owner, "ECONOMIC DOSSIER", d, d.AuthorityBoundary);
        }

        private static void ForkModel(Window owner, DeepSystemsContext ctx, WorldIndex index, EconomicModel source) { string name = Prompt(owner, "FORK ECONOMIC WORLD", "Child economy name", source.Name + " · branch"); if (String.IsNullOrWhiteSpace(name)) return; EconomicModel child = Json.Deserialize<EconomicModel>(Json.Serialize(source)); NormalizeModel(child); child.Id = Id("economic-model"); child.ParentModelId = source.Id; child.Name = name.Trim(); child.SourceKind = "MODEL_FORK"; child.SourceId = source.Id; child.SourceFingerprint = EconomicKernel.Fingerprint(source); child.Status = "ACTIVE"; child.Revision = Math.Max(1, source.Revision) + 1; child.CreatedUtc = Now(); child.UpdatedUtc = child.CreatedUtc; Store.Models.Insert(0, child); Save(ctx); AppendLedger(ctx, "ECONOMY_FORKED", child.Id, "parent " + source.Id, EconomicKernel.Fingerprint(child), ""); OpenModel(owner, ctx, index, child); }

