        private static EcoFirm Firm(string id, string name, string region, string bank, double cash, double equity, double debt, double capital, double capacity, double wage, double markup, string skill, string inventoryGood, double inventory) { EcoFirm f = new EcoFirm { Id = id, Name = name, RegionId = region, BankId = bank, Cash = cash, Equity = equity, Debt = debt, CapitalStock = capital, CapacityBatches = capacity, Productivity = 1, OfferedWage = wage, Markup = markup, TargetInventoryPeriods = 2, RequiredSkill = skill }; f.Inventory[inventoryGood] = inventory; return f; }
        private static EcoProductionRecipe Recipe(string id, string firm, string output, double quantity, double labor, Dictionary<string, double> inputs) { return new EcoProductionRecipe { Id = id, FirmId = firm, OutputGoodId = output, OutputPerBatch = quantity, LaborHoursPerBatch = labor, CapitalUsePerBatch = 1, InputsPerBatch = new Dictionary<string, double>(inputs ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase) }; }
        private static EcoScenario Scenario(string id, string name, double weight, double demand, double productivity, double cost, double wage, double credit, double trade, double inflation) { return new EcoScenario { Id = id, Name = name, Weight = weight, HouseholdDemandMultiplier = demand, ProductivityMultiplier = productivity, InputCostMultiplier = cost, WageMultiplier = wage, CreditAvailabilityMultiplier = credit, TradeFrictionMultiplier = trade, ExogenousInflationMultiplier = inflation, Assumptions = new List<string> { "Declared stress coordinate; not a calibrated probability or forecast." } }; }

        private static void OpenLatestJournal(Window owner, DeepSystemsContext ctx) { Load(ctx); EcoRunArtifact run = ChooseObject(owner, "TRANSACTION CLEARINGHOUSE", "Choose a certified trajectory", Store.Runs.Cast<object>().ToList()) as EcoRunArtifact; if (run == null || run.Result == null) return; OpenRows(owner, "DOUBLE-ENTRY TRANSACTION JOURNAL", run.Result.Journal, "Every retained event balances debit and credit · certificate " + run.CertificateHash); }
        private static void OpenLatestEmployment(Window owner, DeepSystemsContext ctx) { Load(ctx); EcoRunArtifact run = ChooseObject(owner, "LABOR MARKET", "Choose a certified trajectory", Store.Runs.Cast<object>().ToList()) as EcoRunArtifact; if (run == null || run.Result == null) return; OpenRows(owner, "LABOR MARKET", run.Result.Employment, "Employment, hours, gross wages and tax flows in a synthetic run"); }
        private static void OpenLatestAccounts(Window owner, DeepSystemsContext ctx) { Load(ctx); EcoRunArtifact run = ChooseObject(owner, "NATIONAL ACCOUNTS", "Choose a certified trajectory", Store.Runs.Cast<object>().ToList()) as EcoRunArtifact; if (run == null || run.Result == null) return; OpenRows(owner, "NATIONAL ACCOUNTS", run.Result.Periods, "GDP, CPI, production, consumption, money, fiscal, debt and trade coordinates"); }
        private static void OpenLatestDistribution(Window owner, DeepSystemsContext ctx) { Load(ctx); EcoRunArtifact run = ChooseObject(owner, "DISTRIBUTION OBSERVATORY", "Choose a certified trajectory", Store.Runs.Cast<object>().ToList()) as EcoRunArtifact; if (run == null || run.Result == null) return; List<object> rows = run.Result.Periods.Select(x => (object)("t" + x.Period + "   ·   wealth Gini " + x.WealthGini.ToString("0.####", CultureInfo.InvariantCulture) + "   ·   income Gini " + x.IncomeGini.ToString("0.####", CultureInfo.InvariantCulture) + "   ·   unemployment " + x.UnemploymentRate.ToString("P2", CultureInfo.InvariantCulture) + "   ·   wage income " + x.WageIncome.ToString("0.##", CultureInfo.InvariantCulture))).ToList(); rows.AddRange(run.Result.FinalEntities.Where(x => Eq(x.Kind, "HOUSEHOLD")).Cast<object>()); OpenRows(owner, "DISTRIBUTION OBSERVATORY", rows, "Distributional diagnostics are descriptive within the declared synthetic world"); }
        private static void OpenArtifactVault(Window owner, DeepSystemsContext ctx) { Load(ctx); OpenRows(owner, "ECONOMIC ARTIFACT VAULT", Store.Runs.Cast<object>().Concat(Store.StressRuns.Cast<object>()).Concat(Store.PolicySweeps.Cast<object>()).Concat(Store.Structures.Cast<object>()), "Fingerprint-bound trajectories, crises, policy spaces and structural maps"); }
        private static void OpenBaselines(Window owner, DeepSystemsContext ctx) { Load(ctx); OpenRows(owner, "IMMUTABLE ECONOMIC BASELINES", Store.Baselines.Cast<object>().Concat(Store.Baselines.Select(x => (object)(x.Id + "   ·   " + (Eq(x.BaselineFingerprint, BaselineFingerprint(x)) ? "VERIFIED" : "FINGERPRINT MISMATCH")))), "Full snapshots with parent lineage and recomputable SHA-256 identities"); }
        private static void OpenAudit(Window owner, DeepSystemsContext ctx) { Load(ctx); List<object> rows = new List<object>(); foreach (EconomicModel model in Store.Models) { string fp = EconomicKernel.Fingerprint(model); rows.Add((model.Name ?? model.Id) + "   ·   " + fp); rows.AddRange(EconomicKernel.Audit(model).Cast<object>()); foreach (EcoRunArtifact run in Store.Runs.Where(x => Eq(x.ModelId, model.Id))) if (!Eq(run.ModelFingerprint, fp)) rows.Add("HISTORY · run " + run.Id + " correctly remains bound to historical fingerprint " + Short(run.ModelFingerprint, 20)); foreach (EcoStressArtifact stress in Store.StressRuns.Where(x => Eq(x.ModelId, model.Id))) if (!Eq(stress.ModelFingerprint, fp)) rows.Add("HISTORY · stress " + stress.Id + " correctly remains bound to historical fingerprint " + Short(stress.ModelFingerprint, 20)); } foreach (EcoModelBaseline b in Store.Baselines) if (!Eq(b.BaselineFingerprint, BaselineFingerprint(b))) rows.Add("BLOCKER · BASELINE_FINGERPRINT_MISMATCH · " + b.Id); List<EcoCivilizationLedgerRecord> ledger = ReadLedger(ctx, 32768); rows.Add("LEDGER · " + VerifyLedger(ledger)); rows.AddRange(ledger.OrderByDescending(x => x.Sequence).Take(256).Cast<object>()); OpenRows(owner, "ECONOMIC PROVENANCE AUDITOR", rows, "Structural references, artifact drift, baseline integrity, append-only chain and non-execution boundaries"); }

        private static List<object> ArtifactsFor(string modelId) { return Store.Runs.Where(x => Eq(x.ModelId, modelId)).Cast<object>().Concat(Store.StressRuns.Where(x => Eq(x.ModelId, modelId)).Cast<object>()).Concat(Store.PolicySweeps.Where(x => Eq(x.ModelId, modelId)).Cast<object>()).Concat(Store.Structures.Where(x => Eq(x.ModelId, modelId)).Cast<object>()).Concat(Store.Capsules.Where(x => Eq(x.ModelId, modelId)).Cast<object>()).Concat(Store.Baselines.Where(x => Eq(x.ModelId, modelId)).Cast<object>()).Concat(Store.Dossiers.Where(x => Eq(x.ModelId, modelId)).Cast<object>()).ToList(); }
        private static void WithModel(Window owner, DeepSystemsContext ctx, Action<EconomicModel> action) { Load(ctx); EconomicModel model = ChooseObject(owner, "SELECT ECONOMY", "Choose an active economic world", Store.Models.Where(x => Active(x.Status)).OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).Cast<object>().ToList()) as EconomicModel; if (model != null && action != null) action(model); }
        private static string CensusLine() { return Store.Models.Count + " economies   ·   " + Store.Runs.Count + " trajectories   ·   " + Store.StressRuns.Count + " stress atlases   ·   " + Store.PolicySweeps.Count + " policy spaces   ·   " + Store.Structures.Count + " structure maps   ·   " + Store.Capsules.Count + " preregistrations   ·   " + Store.Baselines.Count + " baselines   ·   " + Store.Dossiers.Count + " dossiers"; }
        private static string ModelCensus(EconomicModel m) { return m.Regions.Count + " regions · " + m.Goods.Count + " goods · " + m.Households.Count + " household cohorts · " + m.Firms.Count + " firms · " + m.Recipes.Count + " recipes · " + m.Banks.Count + " banks · " + m.Governments.Count + " governments · " + m.Contracts.Count + " contracts · " + m.Loans.Count + " loans · " + m.Scenarios.Count + " stress worlds · T=" + m.Horizon; }

        private static void Load(DeepSystemsContext ctx) { lock (Gate) { if (Store != null && Eq(LoadedRoot, ctx.StateRoot)) return; LoadedRoot = ctx.StateRoot; Store = null; string path = StorePath(ctx); if (File.Exists(path)) try { Store = Json.Deserialize<EconomicCivilizationStore>(File.ReadAllText(path, Encoding.UTF8)); } catch { PreserveCorrupt(path); } if (Store == null && File.Exists(path + ".previous")) try { Store = Json.Deserialize<EconomicCivilizationStore>(File.ReadAllText(path + ".previous", Encoding.UTF8)); } catch { } if (Store == null) Store = new EconomicCivilizationStore(); NormalizeStore(); } }
        private static void NormalizeStore() { if (Store == null) Store = new EconomicCivilizationStore(); Store.Schema = 1; Store.Models = (Store.Models ?? new List<EconomicModel>()).Where(x => x != null).ToList(); Store.Runs = (Store.Runs ?? new List<EcoRunArtifact>()).Where(x => x != null).ToList(); Store.StressRuns = (Store.StressRuns ?? new List<EcoStressArtifact>()).Where(x => x != null).ToList(); Store.PolicySweeps = (Store.PolicySweeps ?? new List<EcoPolicyArtifact>()).Where(x => x != null).ToList(); Store.Structures = (Store.Structures ?? new List<EcoStructureArtifact>()).Where(x => x != null).ToList(); Store.Capsules = (Store.Capsules ?? new List<EcoExperimentCapsule>()).Where(x => x != null).ToList(); Store.Baselines = (Store.Baselines ?? new List<EcoModelBaseline>()).Where(x => x != null).ToList(); Store.Dossiers = (Store.Dossiers ?? new List<EcoEconomicDossier>()).Where(x => x != null).ToList(); foreach (EconomicModel m in Store.Models) NormalizeModel(m); foreach (EcoExperimentCapsule x in Store.Capsules) { x.FrozenParameters = new Dictionary<string, double>(x.FrozenParameters ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase); x.Assumptions = x.Assumptions ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (EcoEconomicDossier x in Store.Dossiers) { x.AccountingConditions = x.AccountingConditions ?? new List<string>(); x.DistributionalEffects = x.DistributionalEffects ?? new List<string>(); x.Alternatives = x.Alternatives ?? new List<string>(); x.Unknowns = x.Unknowns ?? new List<string>(); x.Dissent = x.Dissent ?? new List<string>(); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } }
        private static void NormalizeModel(EconomicModel m) { if (m == null) return; m.Status = String.IsNullOrWhiteSpace(m.Status) ? "ACTIVE" : m.Status; m.Horizon = Math.Max(1, Math.Min(512, m.Horizon)); m.Parameters = new Dictionary<string, double>(m.Parameters ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase); m.Regions = Clean(m.Regions); m.Goods = Clean(m.Goods); m.Households = Clean(m.Households); m.Firms = Clean(m.Firms); m.Recipes = Clean(m.Recipes); m.Banks = Clean(m.Banks); m.Governments = Clean(m.Governments); m.Contracts = Clean(m.Contracts); m.Loans = Clean(m.Loans); m.Scenarios = Clean(m.Scenarios); m.Assumptions = (m.Assumptions ?? new List<string>()).Take(MaxEvidence).ToList(); m.EvidenceNodeIds = (m.EvidenceNodeIds ?? new List<string>()).Take(MaxEvidence).ToList(); foreach (EcoRegion x in m.Regions) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (EcoGood x in m.Goods) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (EcoHousehold x in m.Households) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (EcoFirm x in m.Firms) { x.Inventory = new Dictionary<string, double>(x.Inventory ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (EcoProductionRecipe x in m.Recipes) { x.InputsPerBatch = new Dictionary<string, double>(x.InputsPerBatch ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase); x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (EcoBank x in m.Banks) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (EcoGovernment x in m.Governments) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (EcoContract x in m.Contracts) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (EcoLoan x in m.Loans) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); foreach (EcoScenario x in m.Scenarios) x.Assumptions = x.Assumptions ?? new List<string>(); }
        private static List<T> Clean<T>(IEnumerable<T> values) where T : class { return (values ?? Enumerable.Empty<T>()).Where(x => x != null).Take(MaxEntities).ToList(); }
        private static void TrimStore() { NormalizeStore(); Store.Models = Store.Models.Take(MaxModels).ToList(); Store.Runs = Store.Runs.Take(MaxArtifacts).ToList(); Store.StressRuns = Store.StressRuns.Take(MaxArtifacts).ToList(); Store.PolicySweeps = Store.PolicySweeps.Take(MaxArtifacts).ToList(); Store.Structures = Store.Structures.Take(MaxArtifacts).ToList(); Store.Capsules = Store.Capsules.Take(MaxArtifacts).ToList(); Store.Baselines = Store.Baselines.Take(MaxArtifacts).ToList(); Store.Dossiers = Store.Dossiers.Take(MaxArtifacts).ToList(); }
        private static void Save(DeepSystemsContext ctx) { lock (Gate) { TrimStore(); Store.Revision = Math.Max(0, Store.Revision) + 1; Store.UpdatedUtc = Now(); Store.LastCommitId = Id("economic-commit"); string path = StorePath(ctx); Directory.CreateDirectory(Path.GetDirectoryName(path)); AtomicWrite(path, Json.Serialize(Store)); } }
        private static void AtomicWrite(string path, string text) { string temp = path + ".tmp." + Guid.NewGuid().ToString("N"); File.WriteAllText(temp, text ?? "", new UTF8Encoding(false)); if (File.Exists(path)) { string previous = path + ".previous"; try { File.Replace(temp, path, previous, true); return; } catch { try { File.Copy(path, previous, true); } catch { } } } if (File.Exists(path)) File.Delete(path); File.Move(temp, path); }
        private static void PreserveCorrupt(string path) { try { if (!File.Exists(path)) return; byte[] bytes = File.ReadAllBytes(path); string destination = path + ".corrupt." + HashBytes(bytes).Substring(0, 16) + ".json"; if (!File.Exists(destination)) File.Copy(path, destination); } catch { } }
        private static string StorePath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-economic-civilization.json"); }
        private static string LedgerPath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-economic-civilization-ledger.jsonl"); }
        private static void AppendLedger(DeepSystemsContext ctx, string evt, string subject, string detail, string fingerprint, string certificate) { lock (Gate) try { Directory.CreateDirectory(ctx.StateRoot); List<EcoCivilizationLedgerRecord> prior = ReadLedger(ctx, 32768); EcoCivilizationLedgerRecord last = prior.OrderByDescending(x => x.Sequence).FirstOrDefault(); EcoCivilizationLedgerRecord r = new EcoCivilizationLedgerRecord { Schema = 1, Sequence = last == null ? 1 : last.Sequence + 1, Utc = Now(), Event = Short(evt, 120), Subject = Short(subject, 512), Detail = Short(detail, MaxLongText), CorrelationId = Store == null ? "" : Store.LastCommitId, ModelFingerprint = Short(fingerprint, 128), CertificateHash = Short(certificate, 128), PrevHash = last == null ? new string('0', 64) : last.EntryHash }; r.EntryHash = LedgerHash(r); byte[] bytes = Encoding.UTF8.GetBytes(Json.Serialize(r) + Environment.NewLine); using (FileStream stream = new FileStream(LedgerPath(ctx), FileMode.Append, FileAccess.Write, FileShare.Read, 4096, FileOptions.WriteThrough)) { stream.Write(bytes, 0, bytes.Length); stream.Flush(); } } catch { } }
        private static List<EcoCivilizationLedgerRecord> ReadLedger(DeepSystemsContext ctx, int cap) { List<EcoCivilizationLedgerRecord> rows = new List<EcoCivilizationLedgerRecord>(); if (!File.Exists(LedgerPath(ctx))) return rows; try { foreach (string line in TakeLast(File.ReadLines(LedgerPath(ctx)).Where(x => !String.IsNullOrWhiteSpace(x)), cap)) try { EcoCivilizationLedgerRecord row = Json.Deserialize<EcoCivilizationLedgerRecord>(line); if (row != null) rows.Add(row); } catch { } } catch { } return rows; }
        private static string VerifyLedger(List<EcoCivilizationLedgerRecord> rows) { if (rows == null || rows.Count == 0) return "EMPTY LEDGER"; rows = rows.OrderBy(x => x.Sequence).ToList(); long expected = rows[0].Sequence; string prior = expected == 1 ? new string('0', 64) : rows[0].PrevHash; foreach (EcoCivilizationLedgerRecord row in rows) { if (row.Sequence != expected) return "CHAIN GAP @ " + expected; if (!Eq(row.PrevHash, prior)) return "PREV HASH MISMATCH @ " + row.Sequence; if (!Eq(row.EntryHash, LedgerHash(row))) return "ENTRY HASH MISMATCH @ " + row.Sequence; expected++; prior = row.EntryHash; } return "CHAIN VERIFIED · " + rows.Count.ToString(CultureInfo.InvariantCulture) + " RECORDS"; }
        private static string LedgerHash(EcoCivilizationLedgerRecord r) { return HashText(r.Schema + "|" + r.Sequence + "|" + (r.Utc ?? "") + "|" + (r.Event ?? "") + "|" + (r.Subject ?? "") + "|" + (r.Detail ?? "") + "|" + (r.CorrelationId ?? "") + "|" + (r.ModelFingerprint ?? "") + "|" + (r.CertificateHash ?? "") + "|" + (r.PrevHash ?? "")); }

        private static Dictionary<string, double> ParseMap(string raw) { Dictionary<string, double> result = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); foreach (string part in (raw ?? "").Split(new[] { ',', ';', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries)) { int at = part.IndexOf('='); if (at <= 0) continue; string key = part.Substring(0, at).Trim(); if (!String.IsNullOrWhiteSpace(key)) result[key] = Math.Max(0, Number(part.Substring(at + 1).Trim(), 0)); } return result; }
        private static string UniqueKey(string raw, IEnumerable<string> existing) { string stem = SafeKey(raw); if (String.IsNullOrWhiteSpace(stem)) stem = "ENTITY"; HashSet<string> used = new HashSet<string>(existing ?? Enumerable.Empty<string>(), StringComparer.OrdinalIgnoreCase); string candidate = stem; int n = 2; while (used.Contains(candidate)) candidate = stem + "-" + n++; return candidate; }
        private static string SafeKey(string value) { StringBuilder s = new StringBuilder(); foreach (char c in (value ?? "").Trim().ToUpperInvariant()) if (Char.IsLetterOrDigit(c)) s.Append(c); else if (s.Length > 0 && s[s.Length - 1] != '-') s.Append('-'); return s.ToString().Trim('-'); }
        private static double Rate(string raw, double fallback) { return Math.Max(0, Math.Min(1, Number(raw, fallback))); }
        private static bool Active(string status) { return !Eq(status, "ARCHIVED") && !Eq(status, "DISABLED") && !Eq(status, "RETIRED") && !Eq(status, "REJECTED"); }
        private static bool Eq(string a, string b) { return String.Equals(a ?? "", b ?? "", StringComparison.OrdinalIgnoreCase); }
        private static double Number(string raw, double fallback) { double value; return Double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out value) && !Double.IsNaN(value) && !Double.IsInfinity(value) ? value : fallback; }
        private static int Integer(string raw, int fallback, int minimum, int maximum) { int value; if (!Int32.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out value)) value = fallback; return Math.Max(minimum, Math.Min(maximum, value)); }
        private static string Short(string value, int cap) { value = value ?? ""; cap = Math.Max(1, cap); return value.Length <= cap ? value : value.Substring(0, cap - 1) + "…"; }
        private static string HashText(string value) { return HashBytes(Encoding.UTF8.GetBytes(value ?? "")); }
        private static string HashBytes(byte[] value) { using (SHA256 hash = SHA256.Create()) return BitConverter.ToString(hash.ComputeHash(value ?? new byte[0])).Replace("-", "").ToLowerInvariant(); }
        private static string Id(string prefix) { return prefix + "-" + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8); }
        private static string Now() { return DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); }
        private static IEnumerable<T> TakeLast<T>(IEnumerable<T> source, int count) { Queue<T> q = new Queue<T>(); foreach (T item in source ?? Enumerable.Empty<T>()) { q.Enqueue(item); if (q.Count > count) q.Dequeue(); } foreach (T item in q) yield return item; }

        private static Window Shell(Window owner, string title, double width, double height) { return new Window { Title = "YOMI · " + title, Width = width, Height = height, MinWidth = Math.Min(width, 840), MinHeight = Math.Min(height, 580), Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = owner, FontFamily = new FontFamily("Segoe UI") }; }
        private static TextBlock Txt(string value, double size, Brush foreground, FontWeight weight) { return new TextBlock { Text = value ?? "", FontSize = size, Foreground = foreground, FontWeight = weight, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 3) }; }
        private static Button Btn(string label, RoutedEventHandler click) { Button button = new Button { Content = label, Margin = new Thickness(0, 0, 8, 8), Padding = new Thickness(11, 7, 11, 7), Background = Raised, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), MinWidth = 112 }; if (click != null) button.Click += click; return button; }
        private static Button Tile(string title, string description, RoutedEventHandler click) { Button button = new Button { Width = 280, Height = 116, Margin = new Thickness(0, 0, 10, 10), Padding = new Thickness(13), Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), HorizontalContentAlignment = HorizontalAlignment.Stretch, VerticalContentAlignment = VerticalAlignment.Stretch }; StackPanel content = new StackPanel(); content.Children.Add(Txt(title, 14, Accent, FontWeights.Bold)); content.Children.Add(Txt(description, 11.5, Muted, FontWeights.Normal)); button.Content = content; if (click != null) button.Click += click; return button; }
        private static ListBox List() { return new ListBox { Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), Margin = new Thickness(0, 6, 6, 0), Padding = new Thickness(5), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; }
        private static Brush B(string hex) { return new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex)); }
        private static string Prompt(Window owner, string title, string label, string initial) { Window w = Shell(owner, title, 680, 290); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = Txt(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxShortText, Margin = new Thickness(0, 8, 0, 10), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(8) }; DockPanel.SetDock(editor, Dock.Top); root.Children.Add(editor); WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right }; string result = null; buttons.Children.Add(Btn("OK", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); root.Children.Add(buttons); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static string PromptLarge(Window owner, string title, string label, string initial) { Window w = Shell(owner, title, 800, 560); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = Txt(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxLongText, AcceptsReturn = true, AcceptsTab = true, TextWrapping = TextWrapping.Wrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Margin = new Thickness(0, 8, 0, 0), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(10), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; string result = null; buttons.Children.Add(Btn("SAVE", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(editor); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static object ChooseObject(Window owner, string title, string label, IList<object> choices) { if (choices == null || choices.Count == 0) { MessageBox.Show(owner, "No records are available yet.", title, MessageBoxButton.OK, MessageBoxImage.Information); return null; } Window w = Shell(owner, title, 760, 520); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = Txt(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); ListBox list = List(); list.ItemsSource = choices; list.SelectedIndex = 0; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; object result = null; buttons.Children.Add(Btn("SELECT", delegate { result = list.SelectedItem; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); list.MouseDoubleClick += delegate { result = list.SelectedItem; if (result != null) w.DialogResult = true; }; DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(list); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static void OpenRows(Window owner, string title, object value, string subtitle) { Window w = Shell(owner, title, 1260, 840); DockPanel root = new DockPanel { Margin = new Thickness(16) }; StackPanel head = new StackPanel { Margin = new Thickness(0, 0, 0, 10) }; head.Children.Add(Txt(title, 24, Text, FontWeights.Bold)); head.Children.Add(Txt(subtitle, 12, Muted, FontWeights.Normal)); DockPanel.SetDock(head, Dock.Top); root.Children.Add(head); ListBox list = List(); List<object> rows = new List<object>(); System.Collections.IEnumerable sequence = value as System.Collections.IEnumerable; if (sequence != null && !(value is string)) foreach (object item in sequence) rows.Add(item); else if (value != null) rows.Add(value); list.ItemsSource = rows; root.Children.Add(list); w.Content = root; w.Show(); }
    }
